func parseDigitsToDecimal(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, -scale)
	}
	// s contains only digits possibly with spaces; remove spaces
	s = strings.ReplaceAll(s, " ", "")
	if s == "" {
		return decimal.New(0, -scale)
	}
	// parse as integer
	d, err := decimal.NewFromString(s)
	if err != nil {
		// fallback parse int64
		var n int64
		fmt.Sscan(s, &n)
		d = decimal.NewFromInt(n)
	}
	return decimal.New(d.IntPart(), -scale)
}

func truncateToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func storeComm(v decimal.Decimal) decimal.Decimal {
	// PIC 9(6)V99 => scale 2, integer digits 6
	// Truncate to scale 2 then keep low-order digits
	v = v.Truncate(2)
	// handle overflow: keep low 6 integer digits
	// Implement by modulo 10^6 for integer part
	// Use integer arithmetic on scaled value
	scaled := v.Shift(2) // integer value = v*100
	// scaled is integer decimal
	// modulus for total digits 8 (6+2) => 10^8 = 100000000
	mod := decimal.New(1, 8) // 10^8
	// Need to handle negative
	sign := scaled.Sign()
	if sign < 0 {
		scaled = scaled.Abs()
		// keep low digits then reapply sign? COBOL dropping high digits preserves sign?
		// For negative, magnitude low digits kept
		if scaled.GreaterThanOrEqual(mod) {
			scaled = scaled.Mod(mod)
		}
		scaled = scaled.Neg()
	} else {
		if scaled.GreaterThanOrEqual(mod) {
			scaled = scaled.Mod(mod)
		}
	}
	return scaled.Shift(-2)
}

func storeTotal(v decimal.Decimal) decimal.Decimal {
	v = v.Truncate(2)
	scaled := v.Shift(2)
	mod := decimal.New(1, 11) // 9+2=11 digits => 10^11
	sign := scaled.Sign()
	if sign < 0 {
		scaled = scaled.Abs()
		if scaled.GreaterThanOrEqual(mod) {
			scaled = scaled.Mod(mod)
		}
		scaled = scaled.Neg()
	} else {
		if scaled.GreaterThanOrEqual(mod) {
			scaled = scaled.Mod(mod)
		}
	}
	return scaled.Shift(-2)
}

func formatEdited(val decimal.Decimal, picture string) string {
	// Count integer digits (Z and 9 before '.') and fractional digits after '.'
	dotIdx := strings.Index(picture, ".")
	var intPic string
	var fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	// Prepare integer and fractional strings with overflow truncation
	// val may be negative; handle sign? No pictures have sign, assume positive; if negative, minus sign?
	isNeg := val.Sign() < 0
	av := val.Abs()
	// Truncate/round already done before; ensure we truncate to fracDigits scale and get integer part
	av = av.Truncate(int32(fracDigits))
	// Get integer part
	intPart := av.IntPart() // truncates toward zero
	// fractional part: get scaled remainder
	// Build frac string zero-padded
	// Use Shift to get fractional digits
	// Example: val=1000.00, fracDigits=2 -> scaled = 100000
	scaled := av.Shift(int32(fracDigits)) // val * 10^fracDigits
	// scaled int part contains integer+frac
	scaledInt := scaled.IntPart()
	// For negative values scaledInt already positive due to Abs
	// Format scaledInt as zero-padded to intDigits+fracDigits
	totalDigits := intDigits + fracDigits
	s := fmt.Sprintf("%0*d", totalDigits, scaledInt)
	// If s longer than totalDigits, keep low-order digits (high-order dropped)
	if len(s) > totalDigits {
		s = s[len(s)-totalDigits:]
	}
	intStr := s[:intDigits]
	fracStr := ""
	if fracDigits > 0 {
		fracStr = s[intDigits:]
	}

	// Build output buffer same length as picture
	out := []rune(picture)
	// Map digits to Z/9 positions
	// Iterate over picture left to right, assigning digits for int part and frac part separately
	intPos := 0 // index into intStr
	// For int part, iterate over picture's intPic region
	// Need to map picture positions to intStr digits
	// We have intPic may contain commas; those are literals not counted
	// We'll walk output index and assign
	// For integer area (before dot)
	digitIdx := 0
	for i, ch := range picture {
		if dotIdx >= 0 && i == dotIdx {
			continue
		}
		if dotIdx >= 0 && i > dotIdx {
			break
		}
		// i is in integer area
		if ch == 'Z' || ch == '9' {
			if digitIdx < len(intStr) {
				out[i] = rune(intStr[digitIdx])
			} else {
				out[i] = '0'
			}
			digitIdx++
		} else {
			// comma or other literal stays as is for now
		}
		_ = intPos
	}
	if fracDigits > 0 {
		fracIdx := 0
		for i := dotIdx + 1; i < len(picture); i++ {
			ch := rune(picture[i])
			if ch == 'Z' || ch == '9' {
				if fracIdx < len(fracStr) {
					out[i] = rune(fracStr[fracIdx])
				} else {
					out[i] = '0'
				}
				fracIdx++
			}
		}
	}

	// Now apply Z suppression for integer part only
	// Z positions that are leading zeros become spaces, commas inside suppressed zone become spaces
	// Find last integer digit position that is non-suppressed
	// Suppression proceeds left to right until we encounter a non-zero digit in a Z/9? Actually Z suppression: leading zeros replaced by spaces, but 9 always prints
	// For ZZZ,ZZ9 pattern, the final 9 before dot must print even if zero
	// General rule: scan integer Z/9 positions from left to right; if we have not yet encountered a non-zero digit, Z positions with '0' become space
	// 9 positions with '0' still print '0' if it's the last 9? But if leading, 9 would print 0, so suppression stops at 9? However typical COBOL: Z suppression stops when a non-zero appears or when we reach a 9 (which prints 0). But spec says Z replaces leading zero with space, 9 always prints digit. So we need to simulate: iterate integer positions left to right; keep flag suppressed = true; when we see a digit '1'-'9', suppressed becomes false; when we see a '9' position, suppression ends regardless (since it prints 0). Actually if digit is '0' and it's a '9', we should print '0' and mark suppressed false? For remaining left? Let's implement typical: suppressed remains true while all previous considered digits are zero and current picture is Z. If current picture is '9', we never suppress (print digit).

	// Determine suppressed zone: for each integer picture index i, we need to know if it's still in suppressed leading zeros
	suppressed := true
	for i := 0; i < len(picture); i++ {
		if dotIdx >= 0 && i == dotIdx {
			continue
		}
		if dotIdx >= 0 && i > dotIdx {
			break
		}
		ch := rune(picture[i])
		if ch == 'Z' || ch == '9' || (out[i] >= '0' && out[i] <= '9') {
			// This position is a digit position (original picture was Z/9)
			// Check original picture char to know if Z or 9
			orig := rune(picture[i])
			isDigitPos := orig == 'Z' || orig == '9'
			if !isDigitPos {
				continue
			}
			dig := out[i]
			if orig == '9' {
				// 9 always prints, so suppression ends
				if suppressed {
					// If dig is '0' and still suppressed, this 9 should print '0' and suppression ends
					// No change to dig, keep '0'
				}
				suppressed = false
			} else { // Z
				if suppressed {
					if dig == '0' {
						out[i] = ' '
					} else {
						// non-zero, stop suppression
						suppressed = false
					}
				}
			}
		}
	}
	// Now commas inside suppressed zone become spaces
	// Suppressed zone is up to last suppressed digit position? Simpler: any comma that has only spaces to its left (in integer part) becomes space
	// Implement by scanning integer area left to right: keep count of non-space digits seen
	seenNonSpaceDigit := false
	// Need to know for each comma whether there's a non-space digit to its left or right?
	// COBOL rule: commas inside suppressed zone also become spaces
	// That means if all digit positions to left of comma are spaces, comma becomes space
	// So check left side
	for i := 0; i < len(picture); i++ {
		if dotIdx >= 0 && i == dotIdx {
			continue
		}
		if dotIdx >= 0 && i > dotIdx {
			break
		}
		orig := rune(picture[i])
		if orig == ',' {
			// check if any non-space digit to left in integer area
			leftHasDigit := false
			for k := 0; k < i; k++ {
				if dotIdx >= 0 && k == dotIdx {
					continue
				}
				// only consider digit positions
				origK := rune(picture[k])
				if origK == 'Z' || origK == '9' {
					if out[k] != ' ' {
						leftHasDigit = true
						break
					}
				}
			}
			if !leftHasDigit {
				out[i] = ' '
			} else {
				// also if all digits to left are spaces, already handled
				// keep comma
			}
		}
		// Track seenNonSpaceDigit for completeness
		if (orig == 'Z' || orig == '9') && out[i] != ' ' {
			seenNonSpaceDigit = true
		}
		_ = seenNonSpaceDigit
	}

	// Handle sign: if negative, need to prefix minus? Not needed for this program (sales positive)
	if isNeg {
		// Find first non-space digit position and place minus to its left if possible
		// COBOL would show minus sign, but not required here
		for i := len(out) - 1; i >= 0; i-- {
			if out[i] != ' ' && out[i] != ',' && out[i] != '.' {
				if i > 0 && out[i-1] == ' ' {
					out[i-1] = '-'
				} else {
					// overwrite? just prefix
					out[0] = '-'
				}
				break
			}
		}
	}

	return string(out)
}

func formatRate(val decimal.Decimal) string {
