}

func INIT_PARA() {
	tierTable[1].TierLimit = decimal.NewFromFloat(1000.00)
	tierTable[1].TierRate = decimal.RequireFromString("2.50")
	tierTable[2].TierLimit = decimal.NewFromFloat(5000.00)
	tierTable[2].TierRate = decimal.RequireFromString("4.00")
	tierTable[3].TierLimit = decimal.NewFromFloat(20000.00)
	tierTable[3].TierRate = decimal.RequireFromString("5.50")
	tierTable[4].TierLimit = decimal.RequireFromString("999999.99")
	tierTable[4].TierRate = decimal.RequireFromString("7.25")
	// Ensure exact scales: truncate to defined pics
	for i := 1; i <= 4; i++ {
		tierTable[i].TierLimit = tierTable[i].TierLimit.Truncate(2)
		tierTable[i].TierRate = tierTable[i].TierRate.Truncate(2)
	}
}

func READ_PARA() {
	if salesFilePos >= len(salesFileLines) {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	line := salesFileLines[salesFilePos]
	salesFilePos++
	// Pad to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	srId := line[0:4]
	srSalesStr := line[4:12]
	salesRec.SrId = srId
	// SR-SALES PIC 9(6)V99 -> 8 digits implied 2 decimals
	salesRec.SrSales = parseDigitsToDecimal(srSalesStr, 2)
}

func PROCESS_PARA() {
	WsTier = 0
	WsIdx = 1
	for {
		cond1 := WsIdx > 4
		cond2 := WsTier > 0
		if cond1 || cond2 {
			break
		}
		if salesRec.SrSales.Cmp(tierTable[WsIdx].TierLimit) <= 0 {
			WsTier = WsIdx
		}
		WsIdx++
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE(WS-TIER) /100
	rate := tierTable[WsTier].TierRate
	comp := salesRec.SrSales.Mul(rate).Shift(-2)
	comp = comp.Round(2)
	WsComm = storeComm(comp)

	WsTotal = storeTotal(WsTotal.Add(WsComm))
	WsCount++

	WsSalesEd = formatEdited(salesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatRated(tierTable[WsTier].TierRate)
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")

	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	// WS-TIER PIC 9 -> width 1 zero-padded; for single digit same as %d
	tierStr := fmt.Sprintf("%01d", WsTier)
	// SR-ID exactly 4 chars
	fmt.Printf("%s T%s %s %s%% %s\n", salesRec.SrId, tierStr, WsSalesEd, WsRateEd, WsCommEd)
}

func formatRated(d decimal.Decimal) string {
	// ensure formatted as 9.99
	return formatEdited(d, "9.99")
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	// Open input.dat line sequential
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// Remove trailing \r if present (Scanner already strips \n, but \r remains if CRLF)
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		salesFileLines = append(salesFileLines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}

	INIT_PARA()
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
		READ_PARA()
	}
	SUMMARY_PARA()
}

